  ["Interface en français et en anglais, avec détection automatique de la langue du client et choix manuel dans les options."] = "Interface en français et en anglais, avec détection automatique de la langue du client et choix manuel dans les options.",
  ["Jets de dés de groupe / raid"] = "Jets de dés de groupe / raid",
  ["Jeu de base accessible et soutien important grâce aux totems."] = "Jeu de base accessible et soutien important grâce aux totems.",
  ["Joueur contre joueur : combattre d'autres joueurs. C'est une activité, pas un rôle ; toutes les classes peuvent la pratiquer."] = "Joueur contre joueur : combattre d'autres joueurs. C'est une activité, pas un rôle ; toutes les classes peuvent la pratiquer.",
  ["LOW — rang inférieur au rang "] = "LOW — rang inférieur au rang ",
  ["La commande principale devient /sam ; retrouve les mêmes sous-commandes, dont /sam settings, /sam bookdebug et /sam conflicts."] = "La commande principale devient /sam ; retrouve les mêmes sous-commandes, dont /sam settings, /sam bookdebug et /sam conflicts.",
  ["La discrétion aide surtout à préparer son ouverture face aux joueurs."] = "La discrétion aide surtout à préparer son ouverture face aux joueurs.",
  ["La détection des grimoires possédés fonctionne aussi lorsque le familier concerné n’est pas actif."] = "La détection des grimoires possédés fonctionne aussi lorsque le familier concerné n’est pas actif.",
  ["La détection et la protection prennent surtout leur valeur face aux autres joueurs."] = "La détection et la protection prennent surtout leur valeur face aux autres joueurs.",
  ["La gestion de la mana et des incantations reste importante."] = "La gestion de la mana et des incantations reste importante.",
  ["La gestion de l’énergie impose parfois des temps d’attente."] = "La gestion de l’énergie impose parfois des temps d’attente.",
  ["La liste de classe de TrainerSpells peut afficher ECO / OPTIONAL et PVP / PVE PVP sur les sorts renseignés, selon tes réglages et la place disponible. Une case dédiée permet de masquer ces marqueurs dans Affichage."] = "La liste de classe de TrainerSpells peut afficher ECO / OPTIONAL et PVP / PVE PVP sur les sorts renseignés, selon tes réglages et la place disponible. Une case dédiée permet de masquer ces marqueurs dans Affichage.",
  ["La liste est remplacée lorsqu'une nouvelle visite apporte des apprentissages. Les talents et recettes appris hors visite sont aussi suivis."] = "La liste est remplacée lorsqu'une nouvelle visite apporte des apprentissages. Les talents et recettes appris hors visite sont aussi suivis.",
  ["La mana et les grosses pointes de dégâts restent des points de vigilance."] = "La mana et les grosses pointes de dégâts restent des points de vigilance.",
  ["La mana reste une contrainte à surveiller pendant la progression."] = "La mana reste une contrainte à surveiller pendant la progression.",
  ["La mobilité facilite le placement et la poursuite dans les deux activités."] = "La mobilité facilite le placement et la poursuite dans les deux activités.",
  ["La perte ou le mauvais placement du démon pénalise les dégâts."] = "La perte ou le mauvais placement du démon pénalise les dégâts.",
  ["La portée aide à se placer et à garder ses distances."] = "La portée aide à se placer et à garder ses distances.",
  ["La protection contre les dissipations prend surtout de la valeur face aux joueurs."] = "La protection contre les dissipations prend surtout de la valeur face aux joueurs.",
  ["La reprise immédiate d’un ennemi peut demander une bonne préparation."] = "La reprise immédiate d’un ennemi peut demander une bonne préparation.",
  ["La version tank de Farouche utilise surtout la forme d'ours pour encaisser les attaques et garder les ennemis concentrés sur elle. Ses choix de talents et son équipement doivent privilégier cette fonction. La possibilité de changer de forme offre des solutions de secours, mais passer en félin ou lancer un soin ne remplace pas la préparation nécessaire à chaque rôle."] = "La version tank de Farouche utilise surtout la forme d'ours pour encaisser les attaques et garder les ennemis concentrés sur elle. Ses choix de talents et son équipement doivent privilégier cette fonction. La possibilité de changer de forme offre des solutions de secours, mais passer en félin ou lancer un soin ne remplace pas la préparation nécessaire à chaque rôle.",
  ["Langue"] = "Langue",
  ["Langue de l’interface"] = "Langue de l’interface",
  ["Le badge RECENT est placé juste sous les icônes de sorts et de talents pour laisser leur image visible."] = "Le badge RECENT est placé juste sous les icônes de sorts et de talents pour laisser leur image visible.",
  ["Le choix du démon et des bonus doit rester adapté au combat."] = "Le choix du démon et des bonus doit rester adapté au combat.",
  ["Le contrôle aléatoire peut créer une ouverture contre un joueur."] = "Le contrôle aléatoire peut créer une ouverture contre un joueur.",
