  ["Le fonctionnement caractéristique de l’arbre arrive progressivement pendant le leveling."] = "Le fonctionnement caractéristique de l’arbre arrive progressivement pendant le leveling.",
  ["Le guide donne explicitement cette plage; conserver le premier rang si utile."] = "Le guide donne explicitement cette plage; conserver le premier rang si utile.",
  ["Le guide le cite comme facultatif mais souligne l'utilite des pistages en leveling."] = "Le guide le cite comme facultatif mais souligne l'utilite des pistages en leveling.",
  ["Le nombre de bénédictions, sceaux et protections demande de l’apprentissage."] = "Le nombre de bénédictions, sceaux et protections demande de l’apprentissage.",
  ["Le nombre limité de grands bonus offensifs laisse moins de leviers pour une urgence."] = "Le nombre limité de grands bonus offensifs laisse moins de leviers pour une urgence.",
  ["Le placement des alliés et des totems compte pour profiter du soutien."] = "Le placement des alliés et des totems compte pour profiter du soutien.",
  ["Le placement et la portée des totems demandent un suivi régulier."] = "Le placement et la portée des totems demandent un suivi régulier.",
  ["Le prochain palier de métier, comme Minage de compagnon, affiche NEXT au lieu de NOT NOW tant qu’il n’est pas encore apprenable."] = "Le prochain palier de métier, comme Minage de compagnon, affiche NEXT au lieu de NOT NOW tant qu’il n’est pas encore apprenable.",
  ["Le prochain palier d’apprentissage dispose aussi d’un fond jaune lorsque les fonds de statut sont activés."] = "Le prochain palier d’apprentissage dispose aussi d’un fond jaune lorsque les fonds de statut sont activés.",
  ["Le rang 1 conserve une immobilisation de secours en Farouche. Les rangs suivants améliorent le contrôle."] = "Le rang 1 conserve une immobilisation de secours en Farouche. Les rangs suivants améliorent le contrôle.",
  ["Le rang 1 de Bénédiction de sacrifice conserve l'usage de transfert de dégâts ; les rangs suivants restent utiles."] = "Le rang 1 de Bénédiction de sacrifice conserve l'usage de transfert de dégâts ; les rangs suivants restent utiles.",
  ["Le rang 1 de Malédiction de témérité conserve l'effet empêchant la fuite, sans rechercher son effet offensif maximal."] = "Le rang 1 de Malédiction de témérité conserve l'effet empêchant la fuite, sans rechercher son effet offensif maximal.",
  ["Le rang 1 suffit pour l'usage conseillé pendant le leveling selon ton rôle. Le sort lui-même reste utile ; les rangs supérieurs peuvent améliorer ses effets."] = "Le rang 1 suffit pour l'usage conseillé pendant le leveling selon ton rôle. Le sort lui-même reste utile ; les rangs supérieurs peuvent améliorer ses effets.",
  ["Le rôle DPS ne permet pas de remplacer automatiquement un tank ou un soigneur spécialisé."] = "Le rôle DPS ne permet pas de remplacer automatiquement un tank ou un soigneur spécialisé.",
  ["Le rôle de la spécialisation affichée apparaît à gauche du titre du grimoire, avec les icônes et les explications de l’arbre de talents."] = "Le rôle de la spécialisation affichée apparaît à gauche du titre du grimoire, avec les icônes et les explications de l’arbre de talents.",
  ["Le soutien au groupe repose surtout sur les dégâts, interruptions et outils du voleur."] = "Le soutien au groupe repose surtout sur les dégâts, interruptions et outils du voleur.",
  ["Les armes et les caractéristiques de l’équipement ont une grande importance."] = "Les armes et les caractéristiques de l’équipement ont une grande importance.",
  ["Les attaques manquées peuvent provoquer un manque de rage."] = "Les attaques manquées peuvent provoquer un manque de rage.",
  ["Les attaques à distance restent gênées si l’ennemi s’approche trop."] = "Les attaques à distance restent gênées si l’ennemi s’approche trop.",
  ["Les badges du grimoire disparaissent lorsque l’on ouvre un onglet d’un autre addon, puis reviennent avec la liste des sorts."] = "Les badges du grimoire disparaissent lorsque l’on ouvre un onglet d’un autre addon, puis reviennent avec la liste des sorts.",
  ["Les boutons de réinitialisation ouvrent correctement leur confirmation, puis la proposition de rechargement."] = "Les boutons de réinitialisation ouvrent correctement leur confirmation, puis la proposition de rechargement.",
  ["Les cases d’icônes par zone deviennent non modifiables lorsque les icônes sont désactivées globalement, sans perdre leurs valeurs."] = "Les cases d’icônes par zone deviennent non modifiables lorsque les icônes sont désactivées globalement, sans perdre leurs valeurs.",
