  ["Les indications de rôle des arbres de talents disposent d’un cadre doré, contrôlé par l’option des contours."] = "Les indications de rôle des arbres de talents disposent d’un cadre doré, contrôlé par l’option des contours.",
  ["Les livres déjà possédés sont signalés chez le marchand. Le stockage en banque correspond aux dernières informations observées."] = "Les livres déjà possédés sont signalés chez le marchand. Le stockage en banque correspond aux dernières informations observées.",
  ["Les marqueurs de la liste TrainerSpells restent associés aux bons sorts pendant le défilement."] = "Les marqueurs de la liste TrainerSpells restent associés aux bons sorts pendant le défilement.",
  ["Les marqueurs suivent les lignes remplacées par TrainerSpells ; la coloration de ses textes reste sous son contrôle."] = "Les marqueurs suivent les lignes remplacées par TrainerSpells ; la coloration de ses textes reste sous son contrôle.",
  ["Les pièges peuvent retenir des joueurs ou des ennemis en PvE."] = "Les pièges peuvent retenir des joueurs ou des ennemis en PvE.",
