  ["PvP : joueur contre joueur. Toutes les classes peuvent pratiquer cette activité."] = "PvP : joueur contre joueur. Toutes les classes peuvent pratiquer cette activité.",
  ["RECENT : derniers sorts, talents et recettes appris, conservés après rechargement. Consulte Apprentissages récents dans les options."] = "RECENT : derniers sorts, talents et recettes appris, conservés après rechargement. Consulte Apprentissages récents dans les options.",
  ["RECENT repère les derniers sorts, talents et recettes appris dans les vues reconnues du grimoire, des talents, des métiers et de TrainerSpells. La liste reste enregistrée après rechargement ; une visite sans apprentissage conserve la précédente."] = "RECENT repère les derniers sorts, talents et recettes appris dans les vues reconnues du grimoire, des talents, des métiers et de TrainerSpells. La liste reste enregistrée après rechargement ; une visite sans apprentissage conserve la précédente.",
