  ["Report possible en leveling Ombre; capacite sur cibles de haut niveau, menace, soin/groupe a verifier. Pas equivalence de tous les rangs."] = "Report possible en leveling Ombre; capacite sur cibles de haut niveau, menace, soin/groupe a verifier. Pas equivalence de tous les rangs.",
  ["Report propose par le guide de leveling; Rain of Fire/Hellfire exige validation securite et AoE avant recommandation automatique."] = "Report propose par le guide de leveling; Rain of Fire/Hellfire exige validation securite et AoE avant recommandation automatique.",
  ["Reporter cet achat permet d'économiser de l'or pendant le leveling."] = "Reporter cet achat permet d'économiser de l'or pendant le leveling.",
  ["Repère d’usage, pas une obligation de talent ou d’achat."] = "Repère d’usage, pas une obligation de talent ou d’achat.",
  ["Repérer BUY NEW RANK lorsqu’un rang supérieur accessible reste à apprendre, hors achats classés ECO ou OPTIONAL."] = "Repérer BUY NEW RANK lorsqu’un rang supérieur accessible reste à apprendre, hors achats classés ECO ou OPTIONAL.",
  ["Repérer dans le grimoire BEST (plus haut rang appris), LOW (ancien rang appris), ECO (rang suffisant pour l’usage conseillé) et OPTIONAL (achat facultatif selon ses rôles)."] = "Repérer dans le grimoire BEST (plus haut rang appris), LOW (ancien rang appris), ECO (rang suffisant pour l’usage conseillé) et OPTIONAL (achat facultatif selon ses rôles).",
  ["Repérer les exemplaires déjà possédés grâce aux dernières positions connues dans les sacs, la banque et la banque de guilde."] = "Repérer les exemplaires déjà possédés grâce aux dernières positions connues dans les sacs, la banque et la banque de guilde.",
  ["Repérer les grimoires déjà appris et apprenables chez les marchands avec une icône de démon et des marqueurs de livre."] = "Repérer les grimoires déjà appris et apprenables chez les marchands avec une icône de démon et des marqueurs de livre.",
  ["Repérer les sorts déjà connus et apprenables chez le maître de classe grâce à des marqueurs sur les icônes."] = "Repérer les sorts déjà connus et apprenables chez le maître de classe grâce à des marqueurs sur les icônes.",
  ["Resistances selon contenu; aucune extrapolation a une ligne vide du tableau."] = "Resistances selon contenu; aucune extrapolation a une ligne vide du tableau.",
  ["Resistances selon zone/groupe; Frostbrand selon PvP; pas de skip si besoin specifique."] = "Resistances selon zone/groupe; Frostbrand selon PvP; pas de skip si besoin specifique.",
  ["Restauration"] = "Restauration",
  ["Restauration s'appuie beaucoup sur des soins qui continuent d'agir pendant plusieurs secondes. Le joueur anticipe les dégâts, répartit ses effets sur les bons alliés et les complète avec des soins directs lorsque la situation l'exige. Sa force vient du suivi des cibles et de la préparation plutôt que d'une réaction identique à chaque perte de vie."] = "Restauration s'appuie beaucoup sur des soins qui continuent d'agir pendant plusieurs secondes. Le joueur anticipe les dégâts, répartit ses effets sur les bons alliés et les complète avec des soins directs lorsque la situation l'exige. Sa force vient du suivi des cibles et de la préparation plutôt que d'une réaction identique à chaque perte de vie.",
  ["Restauration si tu progresses régulièrement en soignant un groupe. Amélioration ou Élémentaire conviennent pour jouer DPS tout en apportant les totems."] = "Restauration si tu progresses régulièrement en soignant un groupe. Amélioration ou Élémentaire conviennent pour jouer DPS tout en apportant les totems.",
  ["Restauration soigne avec un mélange de soins directs, d'effets sur la durée et de soins qui rebondissent entre les alliés. Les totems complètent ce travail en apportant des bonus et du soutien. Forever enrichit cette base sans en changer l'idée principale : choisir le bon soin pour les blessés et maintenir ses outils de groupe en bonne position."] = "Restauration soigne avec un mélange de soins directs, d'effets sur la durée et de soins qui rebondissent entre les alliés. Les totems complètent ce travail en apportant des bonus et du soutien. Forever enrichit cette base sans en changer l'idée principale : choisir le bon soin pour les blessés et maintenir ses outils de groupe en bonne position.",
  ["Restauration soin; acheter les degats si leveling solo. Le guide cite des rangs tardifs, pas une preuve que le rang 1 suffit."] = "Restauration soin; acheter les degats si leveling solo. Le guide cite des rangs tardifs, pas une preuve que le rang 1 suffit.",
  ["Retenir des ennemis peut protéger le groupe ou empêcher un joueur de poursuivre."] = "Retenir des ennemis peut protéger le groupe ou empêcher un joueur de poursuivre.",
  ["Retrouver certains outils peut aider à survivre ou relancer une offensive."] = "Retrouver certains outils peut aider à survivre ou relancer une offensive.",
  ["Retrouver dans les infobulles les indications d’apprentissage et de niveau de déblocage du familier."] = "Retrouver dans les infobulles les indications d’apprentissage et de niveau de déblocage du familier.",
  ["Retrouver les conseils ECO et OPTIONAL chez le maître de classe et dans les infobulles de sorts reconnues, y compris hors du grimoire."] = "Retrouver les conseils ECO et OPTIONAL chez le maître de classe et dans les infobulles de sorts reconnues, y compris hors du grimoire.",
  ["Retrouver sa peur plus souvent aide surtout à se dégager des joueurs."] = "Retrouver sa peur plus souvent aide surtout à se dégager des joueurs.",
  ["Retrouver son étourdissement plus souvent aide à gérer une menace."] = "Retrouver son étourdissement plus souvent aide à gérer une menace.",
  ["Rythme actif, avec des dégâts réguliers et de nombreux contrôles."] = "Rythme actif, avec des dégâts réguliers et de nombreux contrôles.",
  ["Réactiver les catégories d'affichage et les conseils. Les rôles sont reproposés selon tes talents actuels ou le leveling conseillé."] = "Réactiver les catégories d'affichage et les conseils. Les rôles sont reproposés selon tes talents actuels ou le leveling conseillé.",
  ["Réactivité pour un soin ou un sort urgent dans les deux activités."] = "Réactivité pour un soin ou un sort urgent dans les deux activités.",
  ["Récupération de vie limitée et gestion des ressources nécessaire sur la durée."] = "Récupération de vie limitée et gestion des ressources nécessaire sur la durée.",
  ["Réinitialisation"] = "Réinitialisation",
  ["Réinitialisation effectuée. Recharger l'interface maintenant ?\nAvec « Plus tard », tes choix sont conservés et tu peux utiliser /reload quand tu le souhaites."] = "Réinitialisation effectuée. Recharger l'interface maintenant ?\nAvec « Plus tard », tes choix sont conservés et tu peux utiliser /reload quand tu le souhaites.",
  ["Réponse immédiate pour soigner ou infliger des dégâts."] = "Réponse immédiate pour soigner ou infliger des dégâts.",
  ["Résister aux contrôles est surtout utile face aux joueurs."] = "Résister aux contrôles est surtout utile face aux joueurs.",
  ["Résurrection : le rang 1 permet de ressusciter ; les rangs suivants rendent davantage de vie et de mana."] = "Résurrection : le rang 1 permet de ressusciter ; les rangs suivants rendent davantage de vie et de mana.",
  ["Rétablir l'affichage, les conseils et les choix de rôle par défaut pour ce personnage ?"] = "Rétablir l'affichage, les conseils et les choix de rôle par défaut pour ce personnage ?",
  ["Rétablir les options ou relancer le premier lancement depuis Réinitialisation, avec confirmation puis Recharger l’interface / Plus tard."] = "Rétablir les options ou relancer le premier lancement depuis Réinitialisation, avec confirmation puis Recharger l’interface / Plus tard.",
  ["Rétablir les options par défaut"] = "Rétablir les options par défaut",
  ["Rétablis les réglages ou teste à nouveau le premier lancement. Les sorts du familier et les livres enregistrés sont conservés."] = "Rétablis les réglages ou teste à nouveau le premier lancement. Les sorts du familier et les livres enregistrés sont conservés.",
  ["Rôles et spécialisations"] = "Rôles et spécialisations",
  ["Rôles et talents : résumés des spécialisations, recommandation LEVELING et repères PVP / PVE PVP sur les entrées renseignées."] = "Rôles et talents : résumés des spécialisations, recommandation LEVELING et repères PVP / PVE PVP sur les entrées renseignées.",
  ["Sacre soin; tanking hybride, generation de menace et controle changent les priorites."] = "Sacre soin; tanking hybride, generation de menace et controle changent les priorites.",
  ["Sacré"] = "Sacré",
  ["Sacré privilégie les soins tout en conservant les protections, bénédictions et auras du paladin. Forever ajoute des interactions permettant de mieux répondre aux dégâts de groupe, en plus des soins ciblés. Le fonctionnement de base est accessible, mais il faut progressivement apprendre à choisir les bons outils de soutien et à gérer ses sceaux."] = "Sacré privilégie les soins tout en conservant les protections, bénédictions et auras du paladin. Forever ajoute des interactions permettant de mieux répondre aux dégâts de groupe, en plus des soins ciblés. Le fonctionnement de base est accessible, mais il faut progressivement apprendre à choisir les bons outils de soutien et à gérer ses sceaux.",
  ["Sacré propose une large palette de soins pour répondre aux dégâts subis par un allié ou par le groupe. Forever ajoute notamment des outils qui soignent plusieurs personnes ou rebondissent entre les alliés, tout en conservant les soins directs classiques. Le joueur adapte son sort à l'urgence, au nombre de blessés et à sa réserve de mana."] = "Sacré propose une large palette de soins pour répondre aux dégâts subis par un allié ou par le groupe. Forever ajoute notamment des outils qui soignent plusieurs personnes ou rebondissent entre les alliés, tout en conservant les soins directs classiques. Le joueur adapte son sort à l'urgence, au nombre de blessés et à sa réserve de mana.",
  ["Sacs et banques"] = "Sacs et banques",
  ["Select All"] = "Tout sélectionner",
  ["Seulement si aucun tanking prevu."] = "Seulement si aucun tanking prevu.",
  ["Signaler les achats facultatifs chez le maître de classe et dans les infobulles ; dans le grimoire, OPTIONAL se place à droite de BEST. Pendant le leveling (avant le niveau 60), selon tous tes rôles et spécialisations. L'infobulle distingue le sort facultatif, le rang supplémentaire reportable et le cas où le rang 1 suffit pour l'usage conseillé, sans afficher les notes de recherche. Ce conseil ne retire aucun sort et reste indépendant d'ECO. La case Icônes doit aussi être activée pour voir le badge."] = "Signaler les achats facultatifs chez le maître de classe et dans les infobulles ; dans le grimoire, OPTIONAL se place à droite de BEST. Pendant le leveling (avant le niveau 60), selon tous tes rôles et spécialisations. L'infobulle distingue le sort facultatif, le rang supplémentaire reportable et le cas où le rang 1 suffit pour l'usage conseillé, sans afficher les notes de recherche. Ce conseil ne retire aucun sort et reste indépendant d'ECO. La case Icônes doit aussi être activée pour voir le badge.",
  ["Signaler les rangs supérieurs à acheter"] = "Signaler les rangs supérieurs à acheter",
  ["Signaler les recettes déjà apprises"] = "Signaler les recettes déjà apprises",
  ["Signaler les sorts, talents et recettes récemment appris. La liste est conservée après rechargement et remplacée lorsqu’un nouvel apprentissage est enregistré. Une visite sans achat conserve la liste précédente. À la première utilisation, les sorts déjà connus du dernier palier accessible sont présélectionnés si leurs niveaux sont connus."] = "Signaler les sorts, talents et recettes récemment appris. La liste est conservée après rechargement et remplacée lorsqu’un nouvel apprentissage est enregistré. Une visite sans achat conserve la liste précédente. À la première utilisation, les sorts déjà connus du dernier palier accessible sont présélectionnés si leurs niveaux sont connus.",
  ["Skills Already Known devient Skills & More. Retrouve le nouveau nom dans les options, la minicarte et les infobulles, avec la signature By CryptoLogiq dans la fenêtre des options."] = "Skills Already Known devient Skills & More. Retrouve le nouveau nom dans les options, la minicarte et les infobulles, avec la signature By CryptoLogiq dans la fenêtre des options.",
  ["Soigner les alliés pour maintenir le groupe en vie."] = "Soigner les alliés pour maintenir le groupe en vie.",
  ["Soin en groupe; les degats peuvent compter en solo. Ne pas marquer le premier achat de Resurrection."] = "Soin en groupe; les degats peuvent compter en solo. Ne pas marquer le premier achat de Resurrection.",
  ["Soins ciblés et soins sur plusieurs alliés dans une même boîte à outils."] = "Soins ciblés et soins sur plusieurs alliés dans une même boîte à outils.",
  ["Soins ciblés, soutien varié et nouveaux outils pour le groupe."] = "Soins ciblés, soutien varié et nouveaux outils pour le groupe.",
  ["Sorts / compétences"] = "Sorts / compétences",
  ["Sorts du familier (/sam pet)"] = "Sorts du familier (/sam pet)",
  ["Souplesse pour exploiter les outils du chasseur et les capacités du familier."] = "Souplesse pour exploiter les outils du chasseur et les capacités du familier.",
  ["Soutien des totems et nouveaux outils de récupération de mana."] = "Soutien des totems et nouveaux outils de récupération de mana.",
  ["Soutien utile au groupe et progression solo accessible."] = "Soutien utile au groupe et progression solo accessible.",
  ["Soutien varié : bonus, affaiblissements, contrôles et soins de secours."] = "Soutien varié : bonus, affaiblissements, contrôles et soins de secours.",
  ["Spécialisation"] = "Spécialisation",
  ["Spécialisation : "] = "Spécialisation : ",
  ["Spécialisation suivie pour ce rôle. La sélection est conservée si tu décoches puis recoches le rôle."] = "Spécialisation suivie pour ce rôle. La sélection est conservée si tu décoches puis recoches le rôle.",
  ["Survie"] = "Survie",
  ["Survie au contact, utile en solo et contre les joueurs."] = "Survie au contact, utile en solo et contre les joueurs.",
  ["Survie face aux attaques au corps à corps, dans les deux activités."] = "Survie face aux attaques au corps à corps, dans les deux activités.",
  ["Survie personnelle utile sous les attaques, notamment en PvP et en solo."] = "Survie personnelle utile sous les attaques, notamment en PvP et en solo.",
  ["Survie propose un rythme offensif soutenu et utilise plus largement les possibilités du chasseur, à distance comme au corps à corps selon le combat et le choix de talents. Les pièges et les contrôles aident à gérer les déplacements ennemis. L'arbre prend davantage de relief une fois ses talents clés obtenus, plutôt que dès les tout premiers niveaux."] = "Survie propose un rythme offensif soutenu et utilise plus largement les possibilités du chasseur, à distance comme au corps à corps selon le combat et le choix de talents. Les pièges et les contrôles aident à gérer les déplacements ennemis. L'arbre prend davantage de relief une fois ses talents clés obtenus, plutôt que dès les tout premiers niveaux.",
  ["Sélection initiale : sorts déjà connus du palier de niveau "] = "Sélection initiale : sorts déjà connus du palier de niveau ",
  ["Talent Spec and Role"] = "Talents, spécialisation et rôle",
  ["Talents"] = "Talents",
  ["Temps fort offensif de la spécialisation Élémentaire."] = "Temps fort offensif de la spécialisation Élémentaire.",
  ["Temps fort offensif à utiliser en tenant compte du risque défensif."] = "Temps fort offensif à utiliser en tenant compte du risque défensif.",
  ["Totems et contrôles apportant du soutien au groupe."] = "Totems et contrôles apportant du soutien au groupe.",
  ["Un badge LEVELING signale l’arbre conseillé en priorité pour progresser en solo dans chaque classe. Les infobulles des arbres et du grimoire décrivent uniquement la spécialisation survolée."] = "Un badge LEVELING signale l’arbre conseillé en priorité pour progresser en solo dans chaque classe. Les infobulles des arbres et du grimoire décrivent uniquement la spécialisation survolée.",
  ["Un bon résultat demande de choisir quand protéger et quand soigner."] = "Un bon résultat demande de choisir quand protéger et quand soigner.",
  ["Un lanceur de sorts à distance qui affaiblit ses ennemis avec des dégâts sur la durée, puis utilise ses drains entre les renouvellements. Il peut entretenir ses effets sur plusieurs adversaires tout en s'appuyant sur son démon. Son efficacité augmente quand les combats lui laissent le temps d'installer et de maintenir ces effets."] = "Un lanceur de sorts à distance qui affaiblit ses ennemis avec des dégâts sur la durée, puis utilise ses drains entre les renouvellements. Il peut entretenir ses effets sur plusieurs adversaires tout en s'appuyant sur son démon. Son efficacité augmente quand les combats lui laissent le temps d'installer et de maintenir ces effets.",
  ["Un soin immédiat peut sauver un allié dans les deux activités."] = "Un soin immédiat peut sauver un allié dans les deux activités.",
  ["Une dépense trop rapide peut laisser le mage sans mana."] = "Une dépense trop rapide peut laisser le mage sans mana.",
  ["Une incantation instantanée apporte dégâts ou réactivité."] = "Une incantation instantanée apporte dégâts ou réactivité.",
  ["Une part de son utilité est commune aux autres spécialisations de chaman."] = "Une part de son utilité est commune aux autres spécialisations de chaman.",
  ["Une partie du résultat dépend de la fréquence des critiques."] = "Une partie du résultat dépend de la fréquence des critiques.",
  ["Une progression centrée sur les soins est surtout adaptée au jeu en groupe."] = "Une progression centrée sur les soins est surtout adaptée au jeu en groupe.",
  ["Utile en PvE et contre les joueurs, selon ta spécialisation et le combat."] = "Utile en PvE et contre les joueurs, selon ta spécialisation et le combat.",
  ["Utile selon la situation ; tu peux l'apprendre et l'utiliser."] = "Utile selon la situation ; tu peux l'apprendre et l'utiliser.",
  ["Utilitaire situationnel ; conserve son intérêt pour le butin ou les déplacements en camouflage."] = "Utilitaire situationnel ; conserve son intérêt pour le butin ou les déplacements en camouflage.",
  ["Utilitaire; ce sort n'est pas une economie de rangs multiples."] = "Utilitaire; ce sort n'est pas une economie de rangs multiples.",
  ["Utilitaire; conserver si interruption, fuite ou soutien de groupe. Pas ECO automatique."] = "Utilitaire; conserver si interruption, fuite ou soutien de groupe. Pas ECO automatique.",
  ["Valider mes choix"] = "Valider mes choix",
  ["Vindicte"] = "Vindicte",
  ["Vindicte est la voie de dégâts de mêlée du paladin : ses attaques avec une arme se combinent à des effets sacrés, aux sceaux et au Jugement. Il conserve les bénédictions, auras et protections qui lui permettent d'aider son groupe. Bien jouer consiste donc aussi à utiliser ce soutien au bon moment, sans abandonner inutilement sa pression offensive."] = "Vindicte est la voie de dégâts de mêlée du paladin : ses attaques avec une arme se combinent à des effets sacrés, aux sceaux et au Jugement. Il conserve les bénédictions, auras et protections qui lui permettent d'aider son groupe. Bien jouer consiste donc aussi à utiliser ce soutien au bon moment, sans abandonner inutilement sa pression offensive.",
  ["Vindicte est un choix simple et autonome pour les quêtes, avec des attaques régulières, des protections et des soins personnels. Garde une arme adaptée et surveille ta mana."] = "Vindicte est un choix simple et autonome pour les quêtes, avec des attaques régulières, des protections et des soins personnels. Garde une arme adaptée et surveille ta mana.",
  ["Voleur"] = "Voleur",
  ["Vérifier le récapitulatif avant d'activer les conseils pour ces rôles et spécialisations."] = "Vérifier le récapitulatif avant d'activer les conseils pour ces rôles et spécialisations.",
  ["Vérifier un récapitulatif des rôles et spécialisations avec OK / Annuler avant d’activer les conseils. Une sélection non validée est reproposée au prochain chargement."] = "Vérifier un récapitulatif des rôles et spécialisations avec OK / Annuler avant d’activer les conseils. Une sélection non validée est reproposée au prochain chargement.",
  ["[LEVELING] — choix conseillé pour progresser en solo"] = "[LEVELING] — choix conseillé pour progresser en solo",
  ["activé"] = "activé",
  ["désactivé"] = "désactivé",
  ["la dernière version"] = "la dernière version",
  ["|cff00ccffECO|r : rang suffisant pour le leveling selon ton rôle ; économie d'or en reportant des achats, pas d'économie de mana garantie."] = "|cff00ccffECO|r : rang suffisant pour le leveling selon ton rôle ; économie d'or en reportant des achats, pas d'économie de mana garantie.",
  ["|cff00ccffOPTIONAL|r : achat facultatif en leveling pour ton rôle. S'ajoute à droite de BEST ; L'infobulle rappelle qu'il s'agit d'une économie d'or sur un achat facultatif. Facultatif ne veut pas dire inutile."] = "|cff00ccffOPTIONAL|r : achat facultatif en leveling pour ton rôle. S'ajoute à droite de BEST ; L'infobulle rappelle qu'il s'agit d'une économie d'or sur un achat facultatif. Facultatif ne veut pas dire inutile.",
  ["|cff33ff33Avantages|r"] = "|cff33ff33Avantages|r",
  ["|cff33ff33BEST|r : plus haut rang appris, même s'il est seul ; puissance et effets de ce rang."] = "|cff33ff33BEST|r : plus haut rang appris, même s'il est seul ; puissance et effets de ce rang.",
  ["|cff33ff33NEW +|r : sort apprenable maintenant, contour vert et halo animé."] = "|cff33ff33NEW +|r : sort apprenable maintenant, contour vert et halo animé.",
  ["|cff4dff4dAvantages|r"] = "|cff4dff4dAvantages|r",
  ["|cffaaaaaaLOW|r : rang inférieur appris, aux dégâts, soins ou effets potentiellement réduits. Certains contrôles ont une limite de niveau."] = "|cffaaaaaaLOW|r : rang inférieur appris, aux dégâts, soins ou effets potentiellement réduits. Certains contrôles ont une limite de niveau.",
  ["|cffff3333NOT NOW|r : autre indisponibilité, contour rouge."] = "|cffff3333NOT NOW|r : autre indisponibilité, contour rouge.",
  ["|cffff5966[PVP]|r : principalement intéressant contre les joueurs. |cff59d9ff[PVE PVP]|r : utile dans les deux activités. Ces repères d’usage apparaissent sur les talents vérifiés et les sorts apprenables du maître ; ils ne rendent aucun choix obligatoire et restent indépendants d’ECO / OPTIONAL."] = "|cffff5966[PVP]|r : principalement intéressant contre les joueurs. |cff59d9ff[PVE PVP]|r : utile dans les deux activités. Ces repères d’usage apparaissent sur les talents vérifiés et les sorts apprenables du maître ; ils ne rendent aucun choix obligatoire et restent indépendants d’ECO / OPTIONAL.",
  ["|cffff7359Inconvénients|r"] = "|cffff7359Inconvénients|r",
  ["|cffffcc00Skills & More:|r configuration disponible après le combat."] = "|cffffcc00Skills & More:|r configuration disponible après le combat.",
  ["|cffffcc00Skills & More:|r utilise /reload après le combat."] = "|cffffcc00Skills & More:|r utilise /reload après le combat.",
  ["|cffffd100BUY NEW RANK|r : un rang supérieur accessible à ton niveau reste à apprendre. Les achats ECO / OPTIONAL ne déclenchent pas cette alerte. LOW signifie qu'un rang supérieur est déjà appris."] = "|cffffd100BUY NEW RANK|r : un rang supérieur accessible à ton niveau reste à apprendre. Les achats ECO / OPTIONAL ne déclenchent pas cette alerte. LOW signifie qu'un rang supérieur est déjà appris.",
  ["|cffffd100NEXT|r : disponible au prochain palier de niveau pair, contour et fond jaunes."] = "|cffffd100NEXT|r : disponible au prochain palier de niveau pair, contour et fond jaunes.",
  ["|cffffd100[LEVELING] — choix conseillé pour progresser en solo|r"] = "|cffffd100[LEVELING] — choix conseillé pour progresser en solo|r",
  ["À la première utilisation, RECENT présélectionne les sorts déjà connus du dernier palier accessible à ton niveau lorsque leurs niveaux requis sont disponibles. Les prochains apprentissages remplacent cette sélection initiale."] = "À la première utilisation, RECENT présélectionne les sorts déjà connus du dernier palier accessible à ton niveau lorsque leurs niveaux requis sont disponibles. Les prochains apprentissages remplacent cette sélection initiale.",
  ["À l’aise sur les combats longs et contre plusieurs ennemis séparés."] = "À l’aise sur les combats longs et contre plusieurs ennemis séparés.",
  ["Élémentaire"] = "Élémentaire",
  ["Élémentaire combat à distance avec des éclairs et des sorts de feu, tout en soutenant le groupe grâce aux totems. Les attaques qui touchent plusieurs ennemis proches tiennent une place importante dans son arsenal. Le rythme offensif reste abordable, mais les gros enchaînements peuvent coûter beaucoup de mana et demandent de bien placer ses totems."] = "Élémentaire combat à distance avec des éclairs et des sorts de feu, tout en soutenant le groupe grâce aux totems. Les attaques qui touchent plusieurs ennemis proches tiennent une place importante dans son arsenal. Le rythme offensif reste abordable, mais les gros enchaînements peuvent coûter beaucoup de mana et demandent de bien placer ses totems.",
  ["Éléments affichés"] = "Éléments affichés",
  ["Équilibre"] = "Équilibre",
  ["Équilibre joue à distance avec des sorts de nature et des arcanes, ainsi que des dégâts sur la durée. Les talents de Forever encouragent à alterner les grandes incantations selon les effets actifs. Le druide peut aussi interrompre son rythme offensif pour contrôler des ennemis ou apporter des soins de secours, au prix de temps et de mana."] = "Équilibre joue à distance avec des sorts de nature et des arcanes, ainsi que des dégâts sur la durée. Les talents de Forever encouragent à alterner les grandes incantations selon les effets actifs. Le druide peut aussi interrompre son rythme offensif pour contrôler des ennemis ou apporter des soins de secours, au prix de temps et de mana.",
  ["— conseillé pour progresser en solo"] = "— conseillé pour progresser en solo",
  ["Le choix manuel de langue est correctement repris après un rechargement de l’interface."] = "Le choix manuel de langue est correctement repris après un rechargement de l’interface.",
  ["La version officielle démarre correctement lorsque la copie DEV est présente mais non chargée."] = "La version officielle démarre correctement lorsque la copie DEV est présente mais non chargée.",
  ["Les compétences de familiers déjà apprises sont reconnues dans la liste de TrainerSpells."] = "Les compétences de familiers déjà apprises sont reconnues dans la liste de TrainerSpells.",
  ["PET_ABILITIES_LABEL"] = "Compétences des familiers",
  ["Les livres de familiers gardent leurs marqueurs quel que soit le démon actif. Le grimoire des familiers indique les rangs appris, les rangs accessibles à acheter et les apprentissages récents."] = "Les livres de familiers gardent leurs marqueurs quel que soit le démon actif. Le grimoire des familiers indique les rangs appris, les rangs accessibles à acheter et les apprentissages récents.",
  ["Un contour doré lumineux distingue les livres du familier actuellement invoqué."] = "Un contour doré lumineux distingue les livres du familier actuellement invoqué.",
  ["SURVIVAL_DRUID_339"] = "Immobilise un ennemi pour prendre de la distance. Les rangs supérieurs peuvent améliorer le contrôle.",
  ["SURVIVAL_DRUID_5211"] = "Étourdit un ennemi pour interrompre une attaque ou prendre la fuite.",
  ["SURVIVAL_DRUID_1850"] = "Accélère tes déplacements pour fuir ou te repositionner.",
  ["SURVIVAL_DRUID_16689"] = "Aide à immobiliser les ennemis qui te frappent pour te dégager.",
  ["SURVIVAL_DRUID_2893"] = "Retire les poisons sur toi ou un allié.",
  ["SURVIVAL_HUNTER_13163"] = "Améliore l’esquive pour limiter les dégâts au corps à corps.",
  ["SURVIVAL_MAGE_1953"] = "Permet de fuir, de te repositionner ou de sortir de certains contrôles.",
  ["SURVIVAL_MAGE_1463"] = "Absorbe des dégâts en consommant du mana : un outil de secours, pas un bouclier à maintenir systématiquement.",
  ["SURVIVAL_MAGE_130"] = "Ralentit ta chute pour éviter les dégâts de chute.",
  ["SURVIVAL_PALADIN_633"] = "Soin d’urgence majeur pour toi ou un allié.",
  ["SURVIVAL_PRIEST_8122"] = "Éloigne temporairement des ennemis. Leur fuite peut attirer d’autres adversaires ; les rangs peuvent toucher davantage de cibles.",
  ["SURVIVAL_WARLOCK_755"] = "Soigne ton démon avec ta propre vie pour le maintenir en combat. Surveille ta santé pendant la canalisation.",
  ["SURVIVAL_LABEL"] = "Afficher les repères SURVIVAL",
  ["SURVIVAL_DESCRIPTION"] = "Signale les outils de fuite, de contrôle défensif ou de soin d’urgence vérifiés. Survole le repère pour connaître son usage. Ce repère ne garantit pas que le rang 1 suffit.",
  ["SURVIVAL_HINT"] = "Outil de survie : son usage dépend de la situation.",
  ["SURVIVAL_LEGEND"] = "|cff66ffaaSURVIVAL|r : outil de fuite, de contrôle défensif ou de soin d’urgence. Peut accompagner BEST ou ECO ; survole le repère pour connaître son usage.",
  ["Le repère SURVIVAL signale une première sélection d’outils de fuite, de contrôle défensif et de soin d’urgence dans le grimoire, chez les maîtres et dans TrainerSpells. Son affichage est réglable dans Affichage."] = "Le repère SURVIVAL signale une première sélection d’outils de fuite, de contrôle défensif et de soin d’urgence dans le grimoire, chez les maîtres et dans TrainerSpells. Son affichage est réglable dans Affichage.",
  ["AOE_MELEE"] = "Inflige des dégâts à plusieurs ennemis proches au corps à corps.",
  ["AOE_CHANNEL"] = "Inflige des dégâts dans une zone pendant la canalisation.",
  ["AOE_MULTITARGET"] = "Touche plusieurs ennemis : vérifie les cibles proches avant de tirer.",
  ["AOE_AROUND"] = "Inflige des dégâts aux ennemis autour de toi.",
  ["AOE_GROUND"] = "Inflige des dégâts dans la zone ciblée au sol.",
  ["AOE_CONE"] = "Inflige des dégâts à plusieurs ennemis devant toi.",
  ["AOE_UNDEAD_DEMON"] = "Inflige des dégâts de zone aux types de créatures indiqués par le sort.",
  ["AOE_CLEAVE"] = "Permet de toucher une cible supplémentaire proche.",
  ["AOE_TOTEM"] = "Le totem inflige des dégâts aux ennemis proches.",
  ["AOE_SELF_DAMAGE"] = "Inflige des dégâts autour de toi et te blesse aussi : surveille ta vie.",
  ["AOE_LABEL"] = "Afficher les repères AOE",
  ["AOE_HINT"] = "Dégâts de zone ou sur plusieurs cibles.",
  ["AOE_DESCRIPTION"] = "Indique les sorts qui touchent plusieurs ennemis dans le grimoire, chez les maîtres et dans TrainerSpells. Ils ne sont pas classés OPTIONAL par défaut.",
  ["AOE_LEGEND"] = "|cff66ddffAOE|r : dégâts de zone ou sur plusieurs cibles. Par exemple Blizzard, Pluie de feu et Consécration.",
  ["Le repère AOE identifie les dégâts de zone et les attaques multicibles, notamment Blizzard, Pluie de feu et Consécration. Son affichage est réglable dans Affichage."] = "Le repère AOE identifie les dégâts de zone et les attaques multicibles, notamment Blizzard, Pluie de feu et Consécration. Son affichage est réglable dans Affichage.",
  ["Les sorts de zone reconnus ne sont plus conseillés comme des achats OPTIONAL."] = "Les sorts de zone reconnus ne sont plus conseillés comme des achats OPTIONAL.",
  ["AOE_TALENT_ACTIVE"] = "Permet de toucher plusieurs ennemis. Lis la description du talent pour ses conditions.",
  ["AOE_TALENT_IMPROVES"] = "Améliore notamment un sort de zone : dégâts, coût, portée ou contrôle selon le talent. Ne déclenche pas lui-même une attaque de zone.",
  ["AOE_TALENT_SPREAD"] = "Permet à un effet de se propager à des ennemis proches sous les conditions du talent.",
  ["AOE_FIRE_NOVA"] = "Inflige des dégâts autour de ton totem de feu actif.",
  ["Les repères AOE couvrent les neuf classes et les talents vérifiés de leurs arbres, y compris les améliorations de sorts de zone. Les marqueurs restent sous les icônes sans masquer les points dépensés."] = "Les repères AOE couvrent les neuf classes et les talents vérifiés de leurs arbres, y compris les améliorations de sorts de zone. Les marqueurs restent sous les icônes sans masquer les points dépensés.",
  ["CLASS_DRAIN_SOUL"] = "Compétence essentielle du démoniste : permet d’obtenir les fragments d’âme nécessaires à plusieurs invocations et capacités. Le rang 1 conserve cet usage ; les rangs supérieurs augmentent notamment les dégâts.",
  ["CLASS_HINT"] = "Compétence nécessaire à un mécanisme central de ta classe.",
  ["CLASS_LABEL"] = "Afficher les repères CLASS",
  ["CLASS_DESCRIPTION"] = "Signale les compétences essentielles aux mécanismes de classe vérifiés. Pour le démoniste, Drain d’âme fournit les fragments d’âme. Ce repère ne rend pas tous les rangs obligatoires.",
  ["CLASS_LEGEND"] = "|cffcca6ffCLASS|r : compétence essentielle à un mécanisme de classe. Peut accompagner ECO au rang 1 ou BEST sur le plus haut rang appris.",
  ["Drain d’âme porte le repère CLASS pour rappeler son rôle dans la création de fragments d’âme. Il n’affiche plus OPTIONAL ; le rang 1 peut conserver ECO et le plus haut rang appris BEST."] = "Drain d’âme porte le repère CLASS pour rappeler son rôle dans la création de fragments d’âme. Il n’affiche plus OPTIONAL ; le rang 1 peut conserver ECO et le plus haut rang appris BEST.",
  ["TOOLTIP_BADGES_LABEL"] = "Afficher les badges au-dessus des infobulles",
  ["TOOLTIP_BADGES_DESCRIPTION"] = "Réaffiche les marqueurs du sort au-dessus de son infobulle : rang, OPTIONAL, SURVIVAL, AOE, CLASS et RECENT selon le sort. Ils passent sous le cadre si le haut de l’écran manque de place.",
  ["Les badges du sort peuvent aussi s’afficher au-dessus de son infobulle, avec une option dédiée dans Affichage. Ils passent sous le cadre si le haut de l’écran manque de place."] = "Les badges du sort peuvent aussi s’afficher au-dessus de son infobulle, avec une option dédiée dans Affichage. Ils passent sous le cadre si le haut de l’écran manque de place.",
  ["BADGE_EDITOR_TITLE"] = "Badges des sorts",
  ["BADGE_EDITOR_HELP"] = "Personnalise les sorts et talents de ta classe. Choisis un sort de la liste ou saisis un ID, puis enregistre tes choix. BEST, LOW, BUY NEW RANK, RECENT et les statuts appris/apprenable restent calculés automatiquement.",
  ["BADGE_CURRENT_CLASS"] = "Classe actuelle : %s",
  ["BADGE_SCOPE"] = "Appliquer ces réglages à",
  ["BADGE_SCOPE_CHARACTER"] = "Ce personnage",
  ["BADGE_SCOPE_CLASS"] = "Toute cette classe sur mon compte",
  ["BADGE_PRECEDENCE"] = "Les réglages de ce personnage sont prioritaires sur ceux de sa classe. À portée égale, un ID précis est prioritaire sur une règle pour tous les rangs. « Hériter » conserve le choix de la classe ou le conseil fourni.",
  ["BADGE_FILTER"] = "Filtrer la liste par badge",
  ["BADGE_ALL"] = "Tous les sorts de la liste",
  ["BADGE_SPELL"] = "Sort ou talent à modifier",
  ["BADGE_ADD_ID"] = "Ajouter ou sélectionner un ID de sort",
  ["BADGE_ADD_HELP"] = "Saisis l’ID numérique du sort, puis valide le champ. Les choix ci-dessous ne sont appliqués qu’après Enregistrer.",
  ["BADGE_ALL_RANKS"] = "Appliquer à tous les rangs",
  ["BADGE_RANK_HELP"] = "Coché par défaut pour un nouvel ID. Les autres rangs sont reliés par le nom fourni par le jeu. Décoché : seul cet ID est modifié.",
  ["BADGE_FIELD_usage"] = "Usage du sort",
  ["BADGE_FIELD_combat"] = "Activité PVP / PVE PVP",
  ["BADGE_FIELD_advice"] = "Conseil d’achat",
  ["BADGE_INHERIT"] = "Hériter du réglage précédent",
  ["BADGE_NONE"] = "Aucun badge dans cette catégorie",
  ["BADGE_DEFAULT"] = "Conseil fourni par l’addon",
  ["BADGE_EFFECTIVE_FIELD"] = "%s : %s — %s",
  ["BADGE_SAVE"] = "Enregistrer mes choix",
  ["BADGE_RESTORE"] = "Retirer ma règle pour ce sort",
  ["BADGE_RESTORE_CONFIRM"] = "Retirer cette règle pour la portée sélectionnée ? Les réglages hérités s’appliqueront de nouveau.",
  ["BADGE_INVALID_ID"] = "Saisis un ID de sort entier et positif.",
  ["BADGE_UNKNOWN_ID"] = "Ce sort n’est pas encore reconnu par le jeu. Vérifie son ID ou réessaie après le chargement de ses informations.",
  ["BADGE_CUSTOM_REASON"] = "Ce repère vient de tes réglages personnalisés de badges.",
  ["BADGE_CUSTOM_OPTIONAL"] = "OPTIONAL — achat reportable selon ton réglage personnalisé.",
  ["Dans Custom, l’onglet Badges des sorts permet de modifier les repères des sorts et talents de sa classe, ou d’ajouter un ID. Les réglages s’appliquent au personnage ou à toute sa classe sur le compte, avec une option Tous les rangs cochée par défaut."] = "Dans Custom, l’onglet Badges des sorts permet de modifier les repères des sorts et talents de sa classe, ou d’ajouter un ID. Les réglages s’appliquent au personnage ou à toute sa classe sur le compte, avec une option Tous les rangs cochée par défaut.",
  ["Dans TrainerSpells, les compétences de démons mémorisées affichent une coche lorsqu’elles sont déjà apprises, même lorsque les noms des familiers sont traduits et les IDs des grimoires diffèrent de ceux des compétences."] = "Dans TrainerSpells, les compétences de démons mémorisées affichent une coche lorsqu’elles sont déjà apprises, même lorsque les noms des familiers sont traduits et les IDs des grimoires diffèrent de ceux des compétences.",
  ["DEV_TOOLTIP_HINT"] = "Copie de développement de Skills & More active.",
  ["DEV_TOOLS_ENABLE"] = "Activer les outils de développement",
  ["DEV_TOOLS_ENABLE_HELP"] = "Affiche les rapports de diagnostic et les commandes de test, ainsi que le bouton pour rejouer le premier lancement. Désactivé par défaut et enregistré pour ce personnage. Aucun rechargement nécessaire.",
  ["DEV_TOOLS_TITLE"] = "Développement",
  ["DEV_TOOLS_DISABLED_HINT"] = "Skills & More : active les outils de développement dans Affichage pour utiliser cette commande.",
  ["DEV_TOOLS_BOOK_COMMAND"] = "/sam bookdebug — grimoire",
  ["RESET_PLAYER_HELP"] = "Rétablis les réglages de ce personnage. Les sorts du familier et les livres enregistrés sont conservés.",
  ["Une case dans Affichage permet d’activer les outils de développement et de diagnostic. L’onglet dédié et le bouton de test du premier lancement sont masqués lorsque ces outils sont désactivés."] = "Une case dans Affichage permet d’activer les outils de développement et de diagnostic. L’onglet dédié et le bouton de test du premier lancement sont masqués lorsque ces outils sont désactivés.",
  ["OPTIONS_HOME"] = "Accueil",
  ["OPTIONS_NAV_HELP"] = "Choisis une rubrique sous Skills & More dans la liste de gauche pour régler l’affichage, les rôles, les badges ou consulter les nouveautés.",
  ["Les rubriques de réglages sont accessibles directement dans la colonne de gauche d’Options → AddOns, sous Skills & More, pour laisser davantage de place au contenu."] = "Les rubriques de réglages sont accessibles directement dans la colonne de gauche d’Options → AddOns, sous Skills & More, pour laisser davantage de place au contenu.",
  ["Les explications des badges personnalisés et des conseils d’usage suivent correctement la langue choisie, y compris dans les infobulles hors du grimoire."] = "Les explications des badges personnalisés et des conseils d’usage suivent correctement la langue choisie, y compris dans les infobulles hors du grimoire.",
  ["AOE_IMPROVE_RESOURCE"] = "Réduit le coût en ressource des attaques de zone ci-dessous. Le talent ne lance pas lui-même une attaque.",
  ["AOE_IMPROVE_DAMAGE"] = "Augmente les dégâts des sorts de zone ou attaques multicibles ci-dessous.",
  ["AOE_IMPROVE_CRIT"] = "Augmente les chances de coup critique du sort de zone ci-dessous.",
  ["AOE_IMPROVE_SLOW"] = "Ajoute un ralentissement au sort de zone ci-dessous.",
  ["AOE_IMPROVE_REACH"] = "Augmente la portée ou le rayon des sorts de zone ci-dessous, selon le sort.",
  ["AOE_IMPROVE_MANA"] = "Réduit le coût en mana des sorts de zone ci-dessous. Le talent ne lance pas lui-même une attaque.",
  ["AOE_IMPROVE_GROUND"] = "Renforce les dégâts de tes sorts sacrés contre les premiers ennemis entrant dans Consécration. Usage offensif, notamment en build hybride ou en PvP : ce talent n’améliore pas directement les soins. AOE décrit ici son lien avec une zone, pas une recommandation pour tous les soigneurs.",
  ["AOE_IMPROVE_RADIUS"] = "Augmente le rayon du sort de zone ci-dessous.",
  ["AOE_IMPROVE_HOLY_NOVA"] = "Renforce les dégâts sacrés et permet aux dégâts périodiques de Flammes sacrées de rendre une Nova sacrée gratuite, selon les conditions du talent.",
  ["AOE_IMPROVE_SPREAD"] = "Permet au sort ci-dessous de se propager à des ennemis proches à la mort de sa cible. Le sort de base n’est pas une attaque de zone sans cette interaction.",
  ["AOE_IMPROVE_FIRE"] = "Améliore les dégâts et le temps de recharge de Nova de feu, ainsi que la durée du Totem de magma.",
  ["AOE_IMPROVE_RANGE"] = "Augmente la portée des sorts multicibles ci-dessous.",
  ["AOE_IMPROVE_STUN"] = "Permet aux sorts de zone ci-dessous d’étourdir les ennemis touchés, selon les conditions du talent.",
  ["AOE_IMPROVE_WHIRLWIND"] = "Réduit le temps de recharge de Tourbillon et renforce ses dégâts contre l’ennemi le plus proche.",
  ["AOE_RELATED_HEADER"] = "Sorts concernés",
  ["AOE_RELATED_PENDING"] = "Description indisponible pour le moment. Survole à nouveau après le chargement des données du sort.",
  ["AOE_RELATED_UNKNOWN"] = "Sort %d",
  ["Les talents qui améliorent des sorts de zone précisent leur effet et présentent les sorts concernés avec leur icône et leur description du jeu."] = "Les talents qui améliorent des sorts de zone précisent leur effet et présentent les sorts concernés avec leur icône et leur description du jeu.",
  ["SPELL_HINT_JUDGEMENT_SEAL"] = "Jugement nécessite un sceau actif. Si tu ne peux pas l’utiliser, pense à activer un sceau avant de lancer Jugement.",
  ["L’infobulle de Jugement rappelle d’activer un sceau pour pouvoir utiliser ce sort."] = "L’infobulle de Jugement rappelle d’activer un sceau pour pouvoir utiliser ce sort.",
  ["CUSTOM_SETTINGS_TITLE"] = "Custom",
  ["La rubrique Custom regroupe les personnalisations ; son premier onglet Badges des sorts permet de modifier les repères."] = "La rubrique Custom regroupe les personnalisations ; son premier onglet Badges des sorts permet de modifier les repères.",
  ["UTILITY_KICK"] = "Interrompt une incantation ennemie. Les sorts insensibles aux interruptions restent protégés.",
  ["UTILITY_BEAR_KICK"] = "Charge farouche en ours interrompt la cible. La version félin n’a pas cet effet.",
  ["UTILITY_SHIELD_KICK"] = "Interrompt une incantation ennemie ; nécessite un bouclier et les conditions du sort.",
  ["UTILITY_PET_KICK"] = "Interruption du chasseur corrompu : nécessite ce démon et sa compétence disponible.",
  ["UTILITY_KICK_AGGRO"] = "Interrompt une incantation et génère explicitement une forte menace. Ce n’est pas une provocation.",
  ["UTILITY_TAUNT"] = "Provoque la cible pour lui faire attaquer le lanceur, si elle n’est pas insensible.",
  ["UTILITY_FORCED_ATTACK"] = "Force temporairement les ennemis concernés à attaquer le lanceur. Cela ne garantit pas de garder leur attention après la fin de l’effet.",
  ["UTILITY_FORCED_THREAT"] = "Force temporairement la cible à attaquer le lanceur et génère de la menace. Ce n’est pas une égalisation garantie de la menace comme Provocation.",
  ["UTILITY_SEAL_TAUNT"] = "Ce sceau permet à Jugement de provoquer la cible. Activer le sceau seul ne la provoque pas.",
  ["UTILITY_AGGRO"] = "La description du sort indique une génération de menace supplémentaire. Ce badge ne signifie pas que la cible est forcée d’attaquer le lanceur.",
  ["UTILITY_THREAT_BUFF"] = "Augmente la menace générée par les attaques sacrées tant que cet effet est actif. Ce n’est pas une provocation.",
  ["UTILITY_PET_THREAT"] = "Génère de la menace pour le familier ; ne pas confondre avec une provocation forcée de tank.",
  ["UTILITY_TOTEM_THREAT"] = "Le totem génère de la menace sur les ennemis proches pour attirer leur attention. Ce n’est pas une provocation du chaman.",
  ["KICK_LABEL"] = "Afficher KICK — interruptions",
  ["KICK_DESCRIPTION"] = "Identifie les interruptions vérifiées, pas tous les étourdissements ou silences. Peut se cumuler avec AGGRO.",
  ["TAUNT_LABEL"] = "Afficher TAUNT — provocations",
  ["TAUNT_DESCRIPTION"] = "Identifie les provocations et effets d’attaque forcée vérifiés. L’infobulle précise les conditions, notamment Sceau de fureur avec Jugement.",
  ["AGGRO_LABEL"] = "Afficher AGGRO — menace supplémentaire",
  ["AGGRO_DESCRIPTION"] = "Identifie les sorts dont la description indique explicitement une menace supplémentaire. Ne marque pas tous les sorts de dégâts ou soins.",
  ["COMBINATION_LABEL"] = "Afficher les astuces de combinaison",
  ["COMBINATION_DESCRIPTION"] = "Afficher une sélection courte d’astuces de sorts liés dans les infobulles. Les prérequis de talents sont précisés ; aucune rotation complète n’est ajoutée.",
  ["COMBO_SWIFTMEND"] = "Prompte guérison nécessite une Récupération ou un Rétablissement actif sur la cible. Si aucun n’est présent, applique d’abord ce soin sur la durée. Dans Forever, Prompte guérison ne le consomme pas.",
  ["COMBO_DRUID_SWIFTNESS"] = "Ce talent peut rendre Toucher guérisseur instantané : active Rapidité de la nature, puis lance le soin pour répondre à une urgence. Le bonus concerne le prochain sort de nature admissible.",
  ["COMBO_MONGOOSE"] = "Morsure de la mangouste demande normalement d’avoir esquivé une attaque. Aspect du singe augmente les chances d’esquive, ce qui peut aider à la rendre disponible. Certains talents de Survie modifient ce prérequis.",
  ["COMBO_ICE_LANCE"] = "Javelot de glace inflige davantage de dégâts aux cibles gelées, par exemple par Nova de givre. Un simple ralentissement ne suffit pas. Si tu possèdes Doigts de givre, son effet actif permet aussi de bénéficier de cette interaction.",
  ["COMBO_INNER_FOCUS"] = "Utilise Focalisation améliorée avant un gros soin admissible, comme Prière de soins ou Soins supérieurs, pour économiser son coût en mana. Le bonus de critique ne concerne que les sorts qui peuvent faire un critique.",
  ["COMBO_COLD_BLOOD"] = "Sang froid peut préparer une Éviscération renforcée avec tes points de combo. Une autre attaque admissible peut utiliser le bonus avant elle ; le bonus de critique ne garantit pas de toucher la cible.",
  ["COMBO_FIRE_NOVA"] = "Nova de feu se déclenche autour de ton totem de feu actif, pas autour de toi. Place un totem de feu près des ennemis avant de lancer ce sort.",
  ["COMBO_RIPTIDE"] = "Remous améliore Salve de guérison lorsque tu la lances directement sur la cible qui porte cet effet. Choisis ce porteur comme première cible, pas simplement un allié voisin.",
  ["COMBO_SHAMAN_SWIFTNESS"] = "Ce talent permet une Vague de soins instantanée : active Rapidité de la nature, puis lance le soin pour répondre à une urgence. Le prochain sort de nature doit être admissible.",
  ["COMBO_CONFLAGRATE"] = "Conflagration nécessite ton Immolation sur la cible. Elle la consomme normalement ; avec le maximum de points dans Ombre et flammes, ce comportement change. Ne suppose pas que le talent est actif si tu ne l’as pas appris.",
  ["COMBO_REVENGE"] = "Revanche devient disponible après ton blocage, ton esquive ou ta parade. Maîtrise du blocage peut aider à obtenir le blocage, mais il faut encore qu’un ennemi t’attaque.",
  ["Les repères KICK, TAUNT et AGGRO distinguent les interruptions, les provocations ou attaques forcées, et les sorts indiquant explicitement de la menace supplémentaire. Un sort peut cumuler plusieurs usages."] = "Les repères KICK, TAUNT et AGGRO distinguent les interruptions, les provocations ou attaques forcées, et les sorts indiquant explicitement de la menace supplémentaire. Un sort peut cumuler plusieurs usages.",
  ["Une sélection de 12 astuces explique des interactions comme Javelot de glace sur cible gelée, Prompte guérison avec un soin sur la durée, Nova de feu avec un totem de feu et Conflagration avec Immolation. Leur affichage est réglable dans Affichage."] = "Une sélection de 12 astuces explique des interactions comme Javelot de glace sur cible gelée, Prompte guérison avec un soin sur la durée, Nova de feu avec un totem de feu et Conflagration avec Immolation. Leur affichage est réglable dans Affichage.",
  ["Les catégories KICK, TAUNT et AGGRO peuvent être affichées séparément et personnalisées dans Custom, onglet Badges des sorts."] = "Les catégories KICK, TAUNT et AGGRO peuvent être affichées séparément et personnalisées dans Custom, onglet Badges des sorts.",
  ["STANCE_BEAR"] = "Forme orientée tank : elle améliore ta résistance et donne accès aux techniques d’ours. Ton équipement et tes talents restent importants.",
  ["STANCE_CAT"] = "Forme orientée dégâts de mêlée, avec énergie et points de combo. Ce repère ne change pas le rôle que tu as choisi.",
  ["STANCE_MOONKIN"] = "Forme orientée dégâts des sorts. Elle empêche les sorts de soin : quitte cette forme si tu dois soigner.",
  ["STANCE_SHADOW"] = "Forme orientée dégâts d’ombre. Les sorts de soin ne sont pas disponibles dans cette forme.",
  ["STANCE_REDEMPTION"] = "Forme temporaire orientée soins, déclenchée à la mort avec le talent Esprit de rédemption. Ce n’est pas une posture à activer volontairement ni un conseil de mourir.",
  ["STANCE_DEFENSIVE"] = "Posture de référence pour tanker : réduit les dégâts subis et augmente la menace. Un tank peut changer de posture pour utiliser certaines techniques.",
  ["STANCE_BATTLE"] = "Posture polyvalente pour attaquer et accéder à certaines techniques. Le repère DPS n’interdit pas à un tank d’y passer lorsque c’est utile.",
  ["STANCE_BERSERKER"] = "Posture offensive orientée dégâts, avec davantage de risques défensifs. Elle ne remplace pas la posture défensive pour encaisser.",
  ["STANCE_RIGHTEOUS_FURY"] = "Effet orienté tank : augmente la menace de tes attaques sacrées. Vérifie qu’il est adapté à ton rôle avant de l’activer en groupe.",
  ["STANCE_SEAL_FURY"] = "Sceau orienté tank : permet de provoquer avec Jugement. Les conditions du sceau et de l’équipement restent applicables.",
  ["TANK_USAGE_LABEL"] = "Afficher TANK — formes et effets orientés tank",
  ["HEAL_USAGE_LABEL"] = "Afficher HEAL — formes et effets orientés soins",
  ["DPS_USAGE_LABEL"] = "Afficher DPS — formes et postures offensives",
  ["ROLE_USAGE_DESCRIPTION"] = "Indique l’orientation de formes, postures et effets vérifiés. Ne choisit pas ton rôle, ne change pas tes talents et ne signifie pas qu’un autre rôle ne peut jamais utiliser ce sort.",
  ["UTILITY_DEFENSIVE_THREAT"] = "Augmente la menace générée tant que la posture est active. Ce n’est pas une provocation directe.",
  ["Les repères TANK, HEAL et DPS indiquent l’orientation de formes, postures et effets vérifiés, notamment ours, félin, chouettide, forme d’Ombre et Fureur vertueuse. Ils peuvent se cumuler avec AGGRO ou TAUNT sans changer le rôle choisi."] = "Les repères TANK, HEAL et DPS indiquent l’orientation de formes, postures et effets vérifiés, notamment ours, félin, chouettide, forme d’Ombre et Fureur vertueuse. Ils peuvent se cumuler avec AGGRO ou TAUNT sans changer le rôle choisi.",
  ["SURVIVAL_DRUID_22812"] = "Réduit les dégâts physiques reçus et limite le recul des incantations sous les coups. Consulte les conditions du sort.",
  ["SURVIVAL_DRUID_22842"] = "Convertit de la rage en soins en forme d’ours : garde suffisamment de rage pour en bénéficier.",
  ["SURVIVAL_HUNTER_5384"] = "Peut faire perdre aux ennemis leur intérêt pour toi et permettre une sortie de combat. Ne garantit pas une fuite réussie.",
  ["SURVIVAL_HUNTER_781"] = "Réduit ta menace au corps à corps pour aider ton familier ou un allié à reprendre l’attention de l’ennemi.",
  ["SURVIVAL_HUNTER_19263"] = "Améliore temporairement ta défense contre les attaques selon les conditions du talent ; ce n’est pas une invulnérabilité.",
  ["SURVIVAL_HUNTER_1499"] = "Immobilise une cible sensible pour te donner du répit. Les dégâts peuvent rompre le contrôle.",
  ["SURVIVAL_HUNTER_5116"] = "Ralentit la cible pour garder tes distances ou fuir. Un ralentissement n’est pas une immobilisation.",
  ["SURVIVAL_HUNTER_2974"] = "Ralentit un ennemi au corps à corps pour faciliter ton désengagement.",
  ["SURVIVAL_HUNTER_13809"] = "Crée une zone de ralentissement pour prendre de la distance avec plusieurs ennemis.",
  ["SURVIVAL_MAGE_122"] = "Immobilise les ennemis proches pour créer de la distance. Les dégâts peuvent rompre les racines.",
  ["SURVIVAL_MAGE_11958"] = "Immunité temporaire : tu ne peux ni attaquer, ni te déplacer, ni lancer de sorts pendant cet effet.",
  ["SURVIVAL_MAGE_11426"] = "Absorbe des dégâts et protège tes incantations tant que le bouclier tient.",
  ["SURVIVAL_MAGE_543"] = "Absorbe des dégâts de feu. Les autres types de dégâts ne sont pas couverts par ce sort.",
  ["SURVIVAL_MAGE_6143"] = "Absorbe des dégâts de givre. Les autres types de dégâts ne sont pas couverts par ce sort.",
  ["SURVIVAL_MAGE_118"] = "Neutralise temporairement une cible sensible. Les dégâts peuvent rompre l’effet et la cible régénère sa vie pendant le contrôle.",
  ["SURVIVAL_PALADIN_498"] = "Protection temporaire de secours ; empêche tes attaques et techniques physiques pendant l’effet. Applique Longanimité et ne peut pas être utilisée sous ce débuff.",
  ["SURVIVAL_PALADIN_642"] = "Immunité de secours soumise à Longanimité. En tanking, les ennemis peuvent se détourner de toi pendant l’immunité.",
  ["SURVIVAL_PALADIN_1022"] = "Protège des attaques physiques mais empêche les attaques physiques du bénéficiaire. En groupe, vérifie sur qui les ennemis vont se reporter.",
  ["SURVIVAL_PALADIN_1044"] = "Aide toi ou un allié à sortir des entraves de déplacement couvertes par ce sort.",
  ["SURVIVAL_PALADIN_853"] = "Étourdit une cible sensible pour stopper ses actions et te donner du répit. Ce contrôle n’est pas un KICK à verrouillage d’école.",
  ["SURVIVAL_PALADIN_4987"] = "Retire les effets néfastes de magie, poison ou maladie couverts par le sort sur toi ou un allié.",
  ["SURVIVAL_PRIEST_17"] = "Absorbe des dégâts pour protéger immédiatement toi ou un allié. Âme affaiblie peut empêcher une nouvelle application.",
  ["SURVIVAL_PRIEST_586"] = "Réduit temporairement ta menace pour aider les autres à reprendre les ennemis. Ce n’est ni une invisibilité ni une sortie de combat garantie.",
  ["SURVIVAL_PRIEST_6346"] = "Protège contre un prochain effet de peur couvert par le sort. Ce n’est pas une protection contre tous les contrôles.",
  ["SURVIVAL_ROGUE_5277"] = "Améliore temporairement l’esquive contre les attaques auxquelles elle s’applique ; ne protège pas de tous les sorts.",
  ["SURVIVAL_ROGUE_1856"] = "Permet de disparaître et de supprimer des entraves de déplacement. Des dégâts ou la détection peuvent compromettre la fuite.",
  ["SURVIVAL_ROGUE_2983"] = "Accélère tes déplacements pour fuir ou te repositionner.",
  ["SURVIVAL_ROGUE_2094"] = "Désoriente une cible sensible pour gagner du temps ; les dégâts rompent cet effet.",
  ["SURVIVAL_ROGUE_1776"] = "Neutralise brièvement la cible pour souffler ou te soigner. Les dégâts rompent le contrôle ; respecte les conditions de positionnement.",
  ["SURVIVAL_ROGUE_1966"] = "Réduit ta menace pour aider le tank à garder l’ennemi. Ne garantit pas que la cible cesse de t’attaquer.",
  ["SURVIVAL_SHAMAN_5730"] = "Le totem peut détourner l’attention d’ennemis proches pour te donner du répit ; son efficacité dépend de la menace déjà accumulée.",
  ["SURVIVAL_SHAMAN_2484"] = "Ralentit les ennemis proches du totem pour aider à fuir ou à garder ses distances.",
  ["SURVIVAL_SHAMAN_8143"] = "Retire périodiquement certains effets de peur, charme ou sommeil sur les membres concernés du groupe. Ne garantit pas une immunité permanente.",
  ["SURVIVAL_SHAMAN_2645"] = "Forme de déplacement pour fuir ou te repositionner lorsque ses conditions d’utilisation le permettent.",
  ["SURVIVAL_WARLOCK_5782"] = "Fait fuir une cible sensible pour te donner du répit. Sa fuite peut attirer d’autres ennemis et les dégâts peuvent rompre le contrôle.",
  ["SURVIVAL_WARLOCK_6789"] = "Effraie brièvement la cible et te rend de la vie selon les effets du sort : un outil d’urgence.",
  ["SURVIVAL_WARLOCK_5484"] = "Fait fuir plusieurs ennemis sensibles. Anticipe le temps d’incantation et le risque d’attirer d’autres adversaires.",
  ["SURVIVAL_WARLOCK_6229"] = "Absorbe des dégâts d’ombre ; ne protège pas contre toutes les écoles de magie.",
  ["SURVIVAL_WARLOCK_6201"] = "Prépare une pierre de soins à utiliser pour récupérer de la vie en urgence. La création seule ne te soigne pas.",
  ["SURVIVAL_WARRIOR_871"] = "Réduit fortement les dégâts reçus pendant un court instant. Nécessite le bouclier et les conditions de posture du sort.",
  ["SURVIVAL_WARRIOR_12975"] = "Augmente temporairement tes points de vie pour encaisser une urgence. Surveille la fin de l’effet.",
  ["SURVIVAL_WARRIOR_2565"] = "Améliore temporairement le blocage avec un bouclier contre les attaques concernées. Ce n’est pas une immunité générale.",
  ["SURVIVAL_WARRIOR_676"] = "Désarme un ennemi sensible pour limiter les attaques liées à son arme. Certaines cibles y sont insensibles.",
  ["SURVIVAL_WARRIOR_5246"] = "Éloigne ou neutralise temporairement des ennemis sensibles. Leur fuite peut attirer d’autres adversaires.",
  ["Les repères SURVIVAL couvrent désormais 56 familles de sorts des neuf classes, notamment Protection divine et ses deux rangs, les principales immunités, boucliers, fuites et réductions de dégâts."] = "Les repères SURVIVAL couvrent désormais 56 familles de sorts des neuf classes, notamment Protection divine et ses deux rangs, les principales immunités, boucliers, fuites et réductions de dégâts.",
  ["STANCE_DEVOTION"] = "Orientation protection : augmente l’armure des membres proches pour limiter les dégâts physiques concernés. Utile au tank et au groupe, quel que soit le rôle du paladin.",
  ["STANCE_RETRIBUTION"] = "Orientation dégâts : inflige des dégâts sacrés aux ennemis qui frappent les membres protégés. Utile aussi au tank lorsqu’il subit des attaques ; elle n’augmente pas directement toutes les attaques du groupe.",
  ["STANCE_CONCENTRATION"] = "Soutien HEAL / DPS : aide les soigneurs et les lanceurs de sorts à poursuivre leurs incantations lorsqu’ils subissent des dégâts. Ce n’est pas une immunité générale aux interruptions.",
  ["Les auras du paladin affichent leur usage : Dévotion TANK, Vindicte DPS et Concentration HEAL / DPS, avec une explication de leur utilité pour le groupe."] = "Les auras du paladin affichent leur usage : Dévotion TANK, Vindicte DPS et Concentration HEAL / DPS, avec une explication de leur utilité pour le groupe.",
  ["TALENT_ADVICE_RECOMMENDED"] = "Conseillé pour : %s",
  ["TALENT_ADVICE_OFFENSIVE_HYBRID"] = "Pour un build hybride offensif ; améliore les dégâts, pas directement les soins.",
  ["TALENT_ADVICE_PVP_CONTEXT"] = "Conseil principalement orienté PvP ; son intérêt dépend du build et de l’activité.",
  ["Les talents dont la recommandation est vérifiée dans un guide affichent la spécialisation, le rôle et le contexte du build. Les variantes situationnelles sont distinguées du build standard."] = "Les talents dont la recommandation est vérifiée dans un guide affichent la spécialisation, le rôle et le contexte du build. Les variantes situationnelles sont distinguées du build standard.",
  ["TALENT_BUILD_SHOCKPROT"] = "Shockprot, PvE offensif",
  ["TALENT_BUILD_SITUATIONAL"] = "Variante situationnelle Shockprot ; ce n’est pas le build tank standard.",
  ["TALENT_BUILD_RAID"] = "raid PvE",
  ["TALENT_BUILD_RAID_DUNGEON"] = "raid / donjon PvE",
  ["TALENT_BUILD_SHOCKADIN_PVP"] = "Shockadin PvP, arbre Sacré",
  ["TALENT_BUILD_RETPROT_DUNGEON"] = "Retprot / donjon PvE",
  ["TALENT_BUILD_DUNGEON"] = "donjon PvE",
  ["TALENT_BUILD_STANDARD_RET"] = "Vindicte standard, PvE",
  ["RECENT_SPARKLES_LABEL"] = "Étincelles : sorts RECENT absents des barres",
  ["RECENT_SPARKLES_DESCRIPTION"] = "Faire scintiller les sorts récemment appris dans le grimoire tant que leur rang n’est pas détecté dans une barre d’action, même sur une autre page ou via une macro reconnue. Le badge RECENT reste affiché après leur placement. Les macros complexes peuvent ne pas être reconnues.",
  ["Dans le grimoire, des étincelles signalent les sorts RECENT dont le rang n’est pas détecté dans les barres d’action. Elles s’arrêtent après placement ; leur affichage est réglable dans Affichage."] = "Dans le grimoire, des étincelles signalent les sorts RECENT dont le rang n’est pas détecté dans les barres d’action. Elles s’arrêtent après placement ; leur affichage est réglable dans Affichage.",
  ["LEARNING_SPARKLES_LABEL"] = "Étincelles : nouveaux apprentissages disponibles",
  ["LEARNING_SPARKLES_DESCRIPTION"] = "Faire scintiller uniquement les icônes NEW + chez les maîtres de classe et de métiers, ainsi que les recettes reconnues comme non apprises chez les marchands et dans le butin. Respecte les catégories d’affichage ; aucune étincelle sur les infobulles. Les données incomplètes restent sans effet.",
  ["Les icônes NEW + scintillent chez les maîtres de classe et de métiers. Les recettes non apprises reconnues scintillent aussi chez les marchands et dans les fenêtres de butin. L’effet reste limité à l’icône et se règle dans Affichage."] = "Les icônes NEW + scintillent chez les maîtres de classe et de métiers. Les recettes non apprises reconnues scintillent aussi chez les marchands et dans les fenêtres de butin. L’effet reste limité à l’icône et se règle dans Affichage.",
  ["UNUSED_SPELL_TOOLTIP"] = "Nouveau sort acquis : aucune utilisation réussie encore enregistrée.",
  ["UNUSED_SPARKLES_LABEL"] = "Étincelles bleues : sorts RECENT encore inutilisés",
  ["UNUSED_SPARKLES_DESCRIPTION"] = "Faire scintiller en bleu les sorts RECENT placés dans les barres mais encore inutilisés, dans le grimoire et sur les barres reconnues. L’effet s’arrête après la première utilisation réussie de ce rang. Le suivi est conservé après rechargement ; seule une utilisation confirmée par le jeu est comptée.",
  ["ACTION_BAR_CATEGORY"] = "Barres d’action",
  ["ACTION_BAR_CATEGORY_DESCRIPTION"] = "Afficher les étincelles bleues sur les icônes des sorts RECENT encore inutilisés dans les barres d’action, de postures, de formes et d’auras Blizzard / EllesmereUI reconnues. Aucun changement des boutons ni de leurs actions.",
  ["Les sorts RECENT placés dans les barres mais encore inutilisés scintillent en bleu, dans le grimoire et les barres Blizzard / EllesmereUI reconnues. Leur infobulle explique le repère ; il disparaît après la première utilisation réussie. Le suivi est conservé après rechargement."] = "Les sorts RECENT placés dans les barres mais encore inutilisés scintillent en bleu, dans le grimoire et les barres Blizzard / EllesmereUI reconnues. Leur infobulle explique le repère ; il disparaît après la première utilisation réussie. Le suivi est conservé après rechargement.",
  ["Les barres de postures, formes et auras sont reconnues, y compris avec EllesmereUI : les sorts présents cessent d’être signalés comme absents des barres et peuvent scintiller en bleu tant qu’ils restent inutilisés."] = "Les barres de postures, formes et auras sont reconnues, y compris avec EllesmereUI : les sorts présents cessent d’être signalés comme absents des barres et peuvent scintiller en bleu tant qu’ils restent inutilisés.",
  ["De nouveaux repères distinguent les usages des sorts : CLASS, AOE, SURVIVAL, KICK, TAUNT et AGGRO. Les infobulles expliquent leurs conditions ; plusieurs usages peuvent se cumuler."] = "De nouveaux repères distinguent les usages des sorts : CLASS, AOE, SURVIVAL, KICK, TAUNT et AGGRO. Les infobulles expliquent leurs conditions ; plusieurs usages peuvent se cumuler.",
  ["Les formes, postures et auras renseignées affichent TANK, HEAL ou DPS, notamment les auras du paladin. Ces indications ne changent pas le rôle choisi."] = "Les formes, postures et auras renseignées affichent TANK, HEAL ou DPS, notamment les auras du paladin. Ces indications ne changent pas le rôle choisi.",
  ["Dans le grimoire, RECENT scintille en doré si le sort manque dans les barres, puis en bleu après placement tant qu’aucune utilisation réussie n’est enregistrée. Le suivi est conservé après rechargement et le badge RECENT reste après utilisation."] = "Dans le grimoire, RECENT scintille en doré si le sort manque dans les barres, puis en bleu après placement tant qu’aucune utilisation réussie n’est enregistrée. Le suivi est conservé après rechargement et le badge RECENT reste après utilisation.",
  ["Les étincelles bleues apparaissent aussi sur les barres Blizzard et EllesmereUI reconnues, y compris les barres de postures, formes et auras. L’infobulle explique le repère."] = "Les étincelles bleues apparaissent aussi sur les barres Blizzard et EllesmereUI reconnues, y compris les barres de postures, formes et auras. L’infobulle explique le repère.",
  ["Les icônes NEW + scintillent chez les maîtres de classe et de métiers. Les recettes non apprises reconnues scintillent chez les marchands et dans le butin, uniquement autour de leur icône. Ces effets se règlent dans Affichage."] = "Les icônes NEW + scintillent chez les maîtres de classe et de métiers. Les recettes non apprises reconnues scintillent chez les marchands et dans le butin, uniquement autour de leur icône. Ces effets se règlent dans Affichage.",
  ["Dans Custom → Badges des sorts, personnalise les marqueurs d’usage, PvP et d’achat de ta classe, ou ajoute un sort par son ID. Les choix peuvent concerner ce personnage ou toute la classe sur le compte, avec Tous les rangs coché par défaut."] = "Dans Custom → Badges des sorts, personnalise les marqueurs d’usage, PvP et d’achat de ta classe, ou ajoute un sort par son ID. Les choix peuvent concerner ce personnage ou toute la classe sur le compte, avec Tous les rangs coché par défaut.",
  ["Les badges peuvent apparaître au-dessus des infobulles. Dans le grimoire, les catégories sont placées juste au-dessus de BEST, LOW ou ECO pour dégager le nom du sort."] = "Les badges peuvent apparaître au-dessus des infobulles. Dans le grimoire, les catégories sont placées juste au-dessus de BEST, LOW ou ECO pour dégager le nom du sort.",
  ["Une sélection d’astuces explique des combinaisons utiles : Jugement avec un sceau, Javelot de glace sur cible gelée, Prompte guérison avec un soin sur la durée, Nova de feu avec un totem de feu et Conflagration avec Immolation."] = "Une sélection d’astuces explique des combinaisons utiles : Jugement avec un sceau, Javelot de glace sur cible gelée, Prompte guérison avec un soin sur la durée, Nova de feu avec un totem de feu et Conflagration avec Immolation.",
  ["Certains talents du paladin indiquent les spécialisations conseillées avec leur icône et le contexte précis du build du guide. Les variantes situationnelles sont distinguées du build standard."] = "Certains talents du paladin indiquent les spécialisations conseillées avec leur icône et le contexte précis du build du guide. Les variantes situationnelles sont distinguées du build standard.",
  ["Les talents qui améliorent des sorts de zone présentent les sorts concernés avec leurs icônes et descriptions du jeu. Leur repère AOE décrit la mécanique, pas une obligation de choisir le talent."] = "Les talents qui améliorent des sorts de zone présentent les sorts concernés avec leurs icônes et descriptions du jeu. Leur repère AOE décrit la mécanique, pas une obligation de choisir le talent.",
  ["Les rubriques de réglages sont accessibles dans la colonne de gauche d’Options → AddOns, sous Skills & More, pour laisser davantage de place au contenu."] = "Les rubriques de réglages sont accessibles dans la colonne de gauche d’Options → AddOns, sous Skills & More, pour laisser davantage de place au contenu.",
  ["Les explications des badges et des conseils d’usage suivent la langue choisie, y compris hors du grimoire."] = "Les explications des badges et des conseils d’usage suivent la langue choisie, y compris hors du grimoire.",
  ["Dans TrainerSpells, les compétences de démons mémorisées affichent leur coche de sort appris, même avec des noms traduits ou des grimoires portant un autre ID."] = "Dans TrainerSpells, les compétences de démons mémorisées affichent leur coche de sort appris, même avec des noms traduits ou des grimoires portant un autre ID.",
  ["Les sorts de zone reconnus ne sont plus conseillés comme des achats OPTIONAL. Drain d’âme porte CLASS et conserve les conseils de rang adaptés sans être présenté comme un sort facultatif."] = "Les sorts de zone reconnus ne sont plus conseillés comme des achats OPTIONAL. Drain d’âme porte CLASS et conserve les conseils de rang adaptés sans être présenté comme un sort facultatif.",
  ["Les catégories d’usage restent reconnues sur les différents rangs d’un sort. Protection divine est notamment reconnue à ses deux rangs."] = "Les catégories d’usage restent reconnues sur les différents rangs d’un sort. Protection divine est notamment reconnue à ses deux rangs.",
